/** ISO/IEC 17025:2017 audit checklist clause template — seeded from Audit Check list DOCX. */

export type Iso17025ClauseTemplate = {
  clauseNo: string
  clauseMatter: string
}

export const ISO_17025_AUDIT_CLAUSES: Iso17025ClauseTemplate[] = [
  { clauseNo: '4.1', clauseMatter: 'Impartiality' },
  { clauseNo: '4.1.1', clauseMatter: 'Laboratory activities shall be undertaken impartially and structured and managed so as to safeguard impartiality' },
  { clauseNo: '4.1.2', clauseMatter: 'The laboratory management shall be committed to impartiality.' },
  { clauseNo: '4.1.3', clauseMatter: 'The laboratory shall be responsible for the impartiality of its laboratory activities and shall not allow commercial, financial or other pressures to compromise impartiality' },
  { clauseNo: '4.1.4', clauseMatter: 'The laboratory shall identify risks to its impartiality on an on-going basis. This shall include those risks that arise from its activities, or from its relationships, or from the relationships of its personnel. However, such relationships do not necessarily present a laboratory with a risk to impartiality. NOTE: A relationship that threatens the impartiality of the laboratory can be based on ownership, governance, management, personnel, shared resources, finances, contracts, marketing (including branding), and payment of a sales commission or other inducement for the referral of new customers, etc.' },
  { clauseNo: '4.1.5', clauseMatter: 'If a risk to impartiality is identified, the laboratory shall be able to demonstrate how it eliminates or minimizes such risk.' },
  { clauseNo: '4.2', clauseMatter: 'Confidentiality' },
  { clauseNo: '4.2.1', clauseMatter: 'The laboratory shall be responsible, through legally enforceable commitments, for the management of all information obtained or created during the performance of laboratory activities. The laboratory shall inform the customer in advance, of the information it intends to place in the public domain. Except for information that the customer makes publicly available, or when agreed between the laboratory and the customer (e.g. for the purpose of responding to complaints), all other information is considered proprietary information and shall be regarded as confidential' },
  { clauseNo: '4.2.2', clauseMatter: 'When the laboratory is required by law or authorized by contractual arrangements to release confidential information, the customer or individual concerned shall, unless prohibited by law, be notified of the information provided.' },
  { clauseNo: '4.2.3', clauseMatter: 'Information about the customer obtained from sources other than the customer (e.g. complainant, regulators) shall be confidential between the customer and the laboratory. The provider (source) of this information shall be confidential to the laboratory and shall not be shared with the customer, unless agreed by the source.' },
  { clauseNo: '4.2.4', clauseMatter: 'Personnel, including any committee members, contractors, personnel of external bodies, or individuals acting on the laboratory\'s behalf, shall keep confidential all information obtained or created during the performance of laboratory activities, except as required by law.' },
  { clauseNo: '5.1', clauseMatter: 'The laboratory shall be a legal entity, or a defined part of a legal entity, that is legally responsible for its laboratory activities.NOTE: For the purposes of this document, a governmental laboratory is deemed to be a legal entity on the basis of its governmental status.' },
  { clauseNo: '5.2', clauseMatter: 'The laboratory shall identify management that has overall responsibility for the laboratory' },
  { clauseNo: '5.3', clauseMatter: 'The laboratory shall define and document the range of laboratory activities for which it conforms with this document. The laboratory shall only claim conformity with this document for this range of laboratory activities, which excludes externally provided laboratory activities on an ongoing basis.' },
  { clauseNo: '5.4', clauseMatter: 'Laboratory activities shall be carried out in such a way as to meet the requirements of this document, the laboratory’s customers, regulatory authorities and organizations providing recognition. This shall include laboratory activities performed in all its permanent facilities, at sites away from its permanent facilities, in associated temporary or mobile facilities or at a customer\'s facility.' },
  { clauseNo: '5.5', clauseMatter: 'The laboratory shall; a) define the organization and management structure of the laboratory, its place in any parent organization, and the relationships between management, technical operations and support services; b) specify the responsibility, authority and interrelationship of all personnel who manage, perform or verify work affecting the results of laboratory activities; c) document its procedures to the extent necessary to ensure the consistent application of its laboratory activities and the validity of the results.' },
  { clauseNo: '5.6', clauseMatter: 'The laboratory shall have personnel who, irrespective of other responsibilities, have the authority and resources needed to carry out their duties, including; a) implementation, maintenance and improvement of the management system; b) identification of deviations from the management system or from the procedures for performing laboratory activities; c) initiation of actions to prevent or minimize such deviations; d) reporting to laboratory management on the performance of the management system and any need for improvement; e) ensuring the effectiveness of laboratory activities' },
  { clauseNo: '5.7', clauseMatter: 'Laboratory management shall ensure that; a) communication takes place regarding the effectiveness of the management system and the importance of meeting customers\' and other requirements; b) the integrity of the management system is maintained when changes to the management system are planned and implemented' },
  { clauseNo: '6.1', clauseMatter: 'General. The laboratory shall have available the personnel, facilities, equipment, systems and support services necessary to manage and perform its laboratory activities.' },
  { clauseNo: '6.2', clauseMatter: 'Personnel' },
  { clauseNo: '6.2.1', clauseMatter: 'All personnel of the laboratory, either internal or external, that could influence the laboratory activities shall act impartially, be competent and work in accordance with the laboratory\'s management system.' },
  { clauseNo: '6.2.2', clauseMatter: 'The laboratory shall document the competence requirements for each function influencing the results of laboratory activities, including requirements for education, qualification, training, technical knowledge, skills and experience.' },
  { clauseNo: '6.2.3', clauseMatter: 'The laboratory shall ensure that the personnel have the competence to perform laboratory activities for which they are responsible and to evaluate the significance of deviations.' },
  { clauseNo: '6.2.4', clauseMatter: 'The management of the laboratory shall communicate to personnel their duties, responsibilities and authorities.' },
  { clauseNo: '6.2.5', clauseMatter: 'The laboratory shall have procedure(s) and retain records for; a) determining the competence requirements; b) selection of personnel; c) training of personnel; d) supervision of personnel; e) authorization of personnel; f) monitoring competence of personnel.' },
  { clauseNo: '6.2.6', clauseMatter: 'The laboratory shall authorize personnel to perform specific laboratory activities, including but not limited to, the following; a) development, modification, verification and validation of methods; b) analysis of results, including statements of conformity or opinions and interpretations; c) report, review and authorization of results.' },
  { clauseNo: '6.3', clauseMatter: 'Facilities and environmental conditions' },
  { clauseNo: '6.3.1', clauseMatter: 'The facilities and environmental conditions shall be suitable for the laboratory activities and shall not adversely affect the validity of results.NOTE: Influences that can adversely affect the validity of results can include, but are not limited to, microbial contamination, dust, electromagnetic disturbances, radiation, humidity, electrical supply, temperature, sound and vibration.' },
  { clauseNo: '6.3.2', clauseMatter: 'The requirements for facilities and environmental conditions necessary for the performance of the laboratory activities shall be documented.' },
  { clauseNo: '6.3.3', clauseMatter: 'The laboratory shall monitor, control and record environmental conditions in accordance with relevant specifications, methods or procedures or where they influence the validity of the results.' },
  { clauseNo: '6.3.4', clauseMatter: 'Measures to control facilities shall be implemented, monitored and periodically reviewed and shall include, but not be limited to; a) access to and use of areas affecting laboratory activities; b) prevention of contamination, interference or adverse influences on laboratory activities; c) effective separation between areas with incompatible laboratory activities' },
  { clauseNo: '6.3.5', clauseMatter: 'When the laboratory performs laboratory activities at sites or facilities outside its permanent control, it shall ensure that the requirements related to facilities and environmental conditions of this document are met' },
  { clauseNo: '6.4', clauseMatter: 'Equipment' },
  { clauseNo: '6.4.1', clauseMatter: 'The laboratory shall have access to equipment (including, but not limited to, measuring instruments, software, measurement standards, reference materials, reference data, reagents, consumables or auxiliary apparatus) that is required for the correct performance of laboratory activities and that can influence the results. NOTE 1: A multitude of names exist for reference materials and certified reference materials, including reference standards, calibration standards, standard reference materials and quality control materials. ISO 17034 contains additional information on reference material producers (RMPs). RMPs that meet the requirements of ISO 17034 are considered to be competent. Reference materials from RMPs meeting the requirements of ISO 17034 are provided with a product information sheet/certificate that specifies, amongst other characteristics, homogeneity and stability for specified properties and, for certified reference materials, specified properties with certified values, their associated measurement uncertainty and metrological traceability.NOTE 2: ISO Guide 33 provides guidance on the selection and use of reference materials. ISO Guide 80 provides guidance to produce in-house quality control materials.' },
  { clauseNo: '6.4.2', clauseMatter: 'When the laboratory uses equipment outside its permanent control, it shall ensure that the requirements for equipment of this document are met' },
  { clauseNo: '6.4.3', clauseMatter: 'The laboratory shall have a procedure for handling, transport, storage, use and planned maintenance of equipment in order to ensure proper functioning and to prevent contamination or deterioration.' },
  { clauseNo: '6.4.4', clauseMatter: 'The laboratory shall verify that equipment conforms to specified requirements before being placed or returned into service.' },
  { clauseNo: '6.4.5', clauseMatter: 'The equipment used for measurement shall be capable of achieving the measurement accuracy and/or measurement uncertainty required to provide a valid result.' },
  { clauseNo: '6.4.6', clauseMatter: 'Measuring equipment shall be calibrated whenthe measurement accuracy or measurement uncertainty affects the validity of the reported results, and/or calibration of the equipment is required to establish the metrological traceability of the reported results.NOTE: Types of equipment having an effect on the validity of the reported results can include: those used for the direct measurement of the measurand, e.g. use of a balance to perform a mass measurement; those used to make corrections to the measured value, e.g. temperature measurements; those used to obtain a measurement result calculated from multiple quantities' },
  { clauseNo: '6.4.7', clauseMatter: 'The laboratory shall establish a calibration programme, which shall be reviewed and adjusted as necessary in order to maintain confidence in the status of calibration.' },
  { clauseNo: '6.4.8', clauseMatter: 'All equipment requiring calibration or which has a defined period of validity shall be labelled, coded or otherwise identified to allow the user of the equipment to readily identify the status of calibration or period of validity.' },
  { clauseNo: '6.4.9', clauseMatter: 'Equipment that has been subjected to overloading or mishandling, gives questionable results, or has been shown to be defective or outside specified requirements, shall be taken out of service. It shall be isolated to prevent its use or clearly labelled or marked as being out of service until it has been verified to perform correctly. The laboratory shall examine the effect of the defect or deviation from specified requirements and shall initiate the management of nonconforming work procedure (see 7.10).' },
  { clauseNo: '6.4.10', clauseMatter: 'When intermediate checks are necessary to maintain confidence in the performance of the equipment, these checks shall be carried out according to a procedure.' },
  { clauseNo: '6.4.11', clauseMatter: 'When calibration and reference material data include reference values or correction factors, the laboratory shall ensure the reference values and correction factors are updated and implemented, as appropriate, to meet specified requirements.' },
  { clauseNo: '6.4.12', clauseMatter: 'The laboratory shall take practicable measures to prevent unintended adjustments of equipment from invalidating results.' },
  { clauseNo: '6.4.13', clauseMatter: 'Records shall be retained for equipment which can influence laboratory activities. The records shall include the following, where applicable; a) the identity of equipment, including software and firmware version; b) the manufacturer\'s name, type identification, and serial number or other unique identification; c) evidence of verification that equipment conforms with specified requirements; d) the current location; e) calibration dates, results of calibrations, adjustments, acceptance criteria, and the due date of the next calibration or the calibration interval; f) documentation of reference materials, results, acceptance criteria, relevant dates and the period of validity; g) the maintenance plan and maintenance carried out to date, where relevant to the performance of the equipment; h) details of any damage, malfunction, modification to, or repair of, the equipment.' },
  { clauseNo: '6.5', clauseMatter: 'Metrological traceability' },
  { clauseNo: '6.5.1', clauseMatter: 'The laboratory shall establish and maintain metrological traceability of its measurement results by means of a documented unbroken chain of calibrations, each contributing to the measurement uncertainty, linking them to an appropriate reference.NOTE 1: In ISO/IEC Guide 99, metrological traceability is defined as the property of a measurement result whereby the result can be related to a reference through a documented unbroken chain of calibrations, each contributing to the measurement uncertainty. NOTE: 2: See Annex A of ISO/IEC 17025: 2017 for additional information on metrological traceability.' },
  { clauseNo: '6.5.2', clauseMatter: 'The laboratory shall ensure that measurement results are traceable to the International System of Units (SI) through; a) calibration provided by a competent laboratory; orNOTE 1: Laboratories fulfilling the requirements of this document are considered to be competent.; b) certified values of certified reference materials provided by a competent producer with stated metrological traceability to the SI; orNOTE 2: Reference material producers fulfilling the requirements of ISO 17034 are considered to be competent.; c) direct realization of the SI units ensured by comparison, directly or indirectly, with national or international standards.NOTE 3: Details of practical realization of the definitions of some important units are given in the SI brochure' },
  { clauseNo: '6.5.3', clauseMatter: 'When metrological traceability to the SI units is not technically possible, the laboratory shall demonstrate metrological traceability to an appropriate reference, e.g.; a) certified values of certified reference materials provided by a competent producer; b) results of reference measurement procedures, specified methods or consensus standards that are clearly described and accepted as providing measurement results fit for their intended use and ensured by suitable comparison.' },
  { clauseNo: '6.6', clauseMatter: 'Externally provided products and services' },
  { clauseNo: '6.6.1', clauseMatter: 'The laboratory shall ensure that only suitable externally provided products and services that affect laboratory activities are used, when such products and services; a) are intended for incorporation into the laboratory’s own activities; b) are provided, in part or in full, directly to the customer by the laboratory, as received from the external provider; c) are used to support the operation of the laboratory. NOTE: Products can include, for example, measurement standards and equipment, auxiliary equipment, consumable materials and reference materials. Services can include, for example, calibration services, sampling services, testing services, facility and equipment maintenance services, proficiency testing services and assessment and auditing services.' },
  { clauseNo: '6.6.2', clauseMatter: 'The laboratory shall have a procedure and retain records for; a) defining, reviewing and approving the laboratory’s requirements for externally provided products and services; b) defining the criteria for evaluation, selection, monitoring of performance and re-evaluation of the external providers; c) ensuring that externally provided products and services conform to the laboratory’s established requirements, or when applicable, to the relevant requirements of this document, before they are used or directly provided to the customer; d) taking any actions arising from evaluations, monitoring of performance and re-evaluations of the external providers.' },
  { clauseNo: '6.6.3', clauseMatter: 'The laboratory shall communicate its requirements to external providers for; a) the products and services to be provided; b) the acceptance criteria; c) competence, including any required qualification of personnel; d) activities that the laboratory, or its customer, intends to perform at the external provider\'s premises.' },
  { clauseNo: '7.1', clauseMatter: 'Review of requests, tenders and contracts' },
  { clauseNo: '7.1.1', clauseMatter: 'The laboratory shall have a procedure for the review of requests, tenders and contracts. The procedure shall ensure that; a) the requirements are adequately defined, documented and understood; b) the laboratory has the capability and resources to meet the requirements; c) where external providers are used, the requirements of 6.6 are applied and the laboratory advises the customer of the specific laboratory activities to be performed by the external provider and gains the customer\'s approval;NOTE 1: It is recognized that externally provided laboratory activities can occur when: the laboratory has the resources and competence to perform the activities, however, for unforeseen reasons is unable to undertake these in part or full; the laboratory does not have the resources or competence to perform the activities.; d) the appropriate methods or procedures are selected and are capable of meeting the customers\' requirements NOTE 2: For internal or routine customers, review of requests, tenders and contracts can be performed in a simplified way.' },
  { clauseNo: '7.1.2', clauseMatter: 'The laboratory shall inform the customer when the method requested by the customer is considered to be inappropriate or out of date.' },
  { clauseNo: '7.1.3', clauseMatter: 'When the customer requests a statement of conformity to a specification or standard for the test or calibration (e.g. pass/fail, in-tolerance/out of-tolerance), the specification or standard and the decision rule shall be clearly defined. Unless inherent in the requested specification or standard, the decision rule selected shall be communicated to, and agreed with, the customer.NOTE: For further guidance on statements of conformity, see ISO/IEC Guide 98-4.' },
  { clauseNo: '7.1.4', clauseMatter: 'Any differences between the request or tender and the contract shall be resolved before laboratory activities commence. Each contract shall be acceptable both to the laboratory and the customer. Deviations requested by the customer shall not impact the integrity of the laboratory or the validity of the results.' },
  { clauseNo: '7.1.5', clauseMatter: 'The customer shall be informed of any deviation from the contract.' },
  { clauseNo: '7.1.6', clauseMatter: 'If a contract is amended after work has commenced, the contract review shall be repeated and any amendments shall be communicated to all affected personnel.' },
  { clauseNo: '7.1.7', clauseMatter: 'The laboratory shall cooperate with customers or their representatives in clarifying the customer\'s request and in monitoring the laboratory’s performance in relation to the work performed.NOTE: Such cooperation can include; a) providing reasonable access to relevant areas of the laboratory to witness customer-specific laboratory activities; b) preparation, packaging, and dispatch of items needed by the customer for verification purposes.' },
  { clauseNo: '7.1.8', clauseMatter: 'Records of reviews, including any significant changes, shall be retained. Records shall also be retained of pertinent discussions with a customer relating to the customer\'s requirements or the results of the laboratory activities.' },
  { clauseNo: '7.2', clauseMatter: 'Selection, verification and validation of methods' },
  { clauseNo: '7.2.1', clauseMatter: 'Selection and verification of methods' },
  { clauseNo: '7.2.1.1', clauseMatter: 'The laboratory shall use appropriate methods and procedures for all laboratory activities and, where appropriate, for evaluation of the measurement uncertainty as well as statistical techniques for analysis of data.NOTE “Method” as used in this document can be considered synonymous with the term “measurement procedure” as defined in ISO/IEC Guide 99.' },
  { clauseNo: '7.2.1.2', clauseMatter: 'All methods, procedures and supporting documentation, such as instructions, standards, manuals and reference data relevant to the laboratory activities, shall be kept up to date and shall be made readily available to personnel (see 8.3).' },
  { clauseNo: '7.2.1.3', clauseMatter: 'The laboratory shall ensure that it uses the latest valid version of a method unless it is not appropriate or possible to do so. When necessary, the application of the method shall be supplemented with additional details to ensure consistent application.NOTE International, regional or national standards or other recognized specifications that contain sufficient and concise information on how to perform laboratory activities do not need to be supplemented or rewritten as internal procedures if these standards are written in a way that they can be used by the operating personnel in a laboratory. It can be necessary to provide additional documentation for optional steps in the method or additional details.' },
  { clauseNo: '7.2.1.4', clauseMatter: 'When the customer does not specify the method to be used, the laboratory shall select an appropriate method and inform the customer of the method chosen. Methods published either in international, regional or national standards, or by reputable technical organizations, or in relevant scientific texts or journals, or as specified by the manufacturer of the equipment, are recommended. Laboratory-developed or modified methods can also be used.' },
  { clauseNo: '7.2.1.5', clauseMatter: 'The laboratory shall verify that it can properly perform methods before introducing them by ensuring that it can achieve the required performance. Records of the verification shall be retained. If the method is revised by the issuing body, verification shall be repeated to the extent necessary.' },
  { clauseNo: '7.2.1.6', clauseMatter: 'When method development is required, this shall be a planned activity and shall be assigned to competent personnel equipped with adequate resources. As method development proceeds, periodic review shall be carried out to confirm that the needs of the customer are still being fulfilled. Any modifications to the development plan shall be approved and authorized.' },
  { clauseNo: '7.2.1.7', clauseMatter: 'Deviations from methods for all laboratory activities shall occur only if the deviation has been documented, technically justified, authorized, and accepted by the customer.NOTE Customer acceptance of deviations can be agreed in advance in the contract.' },
  { clauseNo: '7.2.2', clauseMatter: 'Validation of methods' },
  { clauseNo: '7.2.2.1', clauseMatter: 'The laboratory shall validate nonstandard methods, laboratory developed methods and standard methods used outside their intended scope or otherwise modified. The validation shall be as extensive as is necessary to meet the needs of the given application or field of application. NOTE 1: Validation can include procedures for sampling, handling and transportation of test orcalibration items.NOTE 2: The techniques used for method validation can be one of, or a combination of, the following; a) calibration or evaluation of bias and precision using reference standards or reference materials; b) systematic assessment of the factors influencing the result; c) testing method robustness through variation of controlled parameters, such as incubator temperature, volume dispensed; d) comparison of results achieved with other validated methods; e) Interlaboratory comparisons; f) evaluation of measurement uncertainty of the results based on an understanding of the theoretical principles of the method and practical experience of the performance of the sampling or test method.' },
  { clauseNo: '7.2.2.2', clauseMatter: 'When changes are made to a validated method, the influence of such changes shall be determined and where they are found to affect the original validation, a new method validation shall be performed.' },
  { clauseNo: '7.2.2.3', clauseMatter: 'The performance characteristics of validated methods, as assessed for the intended use, shall be relevant to the customers\' needs and consistent with specified requirements.NOTE: Performance characteristics can include, but are not limited to, measurement range, accuracy, measurement uncertainty of the results, limit of detection, limit of quantification, selectivity of the method, linearity, repeatability or reproducibility, robustness against external influences or cross sensitivity against interference from the matrix of the sample or test object, and bias.' },
  { clauseNo: '7.2.2.4', clauseMatter: 'The laboratory shall retain the following records of validation; a) the validation procedure used; b) specification of the requirements; c) determination of the performance characteristics of the method; d) results obtained; e) a statement on the validity of the method, detailing its fitness for the intended use.' },
  { clauseNo: '7.3', clauseMatter: 'Sampling' },
  { clauseNo: '7.3.1', clauseMatter: 'The laboratory shall have a sampling plan and method when it carries out sampling of substances, materials or products for subsequent testing or calibration. The sampling method shall address the factors to be controlled to ensure the validity of subsequent testing or calibration results. The sampling plan and method shall be available at the site where sampling is undertaken. Sampling plans shall, whenever reasonable, be based on appropriate statistical methods.' },
  { clauseNo: '7.3.2', clauseMatter: 'The sampling method shall describe; a) the selection of samples or sites; b) the sampling plan; c) the preparation and treatment of sample(s) from a substance, material or product to yield the required item for subsequent testing or calibration.NOTE: When received into the laboratory, further handling can be required as specified in 7.4.' },
  { clauseNo: '7.3.3', clauseMatter: 'The laboratory shall retain records of sampling data that forms part of the testing or calibration that is undertaken. These records shall include, where relevant; a) reference to the sampling method used; b) date and time of sampling; c) data to identify and describe the sample (e.g. number, amount, name); d) identification of the personnel performing sampling; e) identification of the equipment used; f) environmental or transport conditions; g) diagrams or other equivalent means to identify the sampling location, when appropriate; h) deviations, additions to or exclusions from the sampling method and sampling plan.' },
  { clauseNo: '7.4', clauseMatter: 'Handling of test or calibration items' },
  { clauseNo: '7.4.1', clauseMatter: 'The laboratory shall have a procedure for the transportation, receipt, handling, protection, storage, retention, and disposal or return of test or calibration items, including all provisions necessary to protect the integrity of the test or calibration item, and to protect the interests of the laboratory and the customer. Precautions shall be taken to avoid deterioration, contamination, loss or damage to the item during handling, transporting, storing/waiting, and preparation for testing orcalibration. Handling instructions provided with the item shall be followed.' },
  { clauseNo: '7.4.2', clauseMatter: 'The laboratory shall have a system for the unambiguous identification of test or calibration items. The identification shall be retained while the item is under the responsibility of the laboratory. The system shall ensure that items will not be confused physically or when referred to in records or other documents. The system shall, if appropriate, accommodate a sub-division of an item or groups of items and the transfer of items.' },
  { clauseNo: '7.4.3', clauseMatter: 'Upon receipt of the test or calibration item, deviations from specified conditions shall be recorded. When there is doubt about the suitability of an item for test or calibration, or when an item does not conform to the description provided, the laboratory shall consult the customer for further instructions before proceeding and shall record the results of this consultation. When the customer requires the item to be tested or calibrated acknowledging a deviation from specified conditions, the laboratory shall include a disclaimerin the report indicating which results may be affected by the deviation.' },
  { clauseNo: '7.4.4', clauseMatter: 'When items need to be stored or conditioned under specified environmental conditions, these conditions shall be maintained, monitored and recorded.' },
  { clauseNo: '7.5', clauseMatter: 'Technical Records' },
  { clauseNo: '7.5.1', clauseMatter: 'The laboratory shall ensure that technical records for each laboratory activity contain the results, report and sufficient information to facilitate, if possible, identification of factors affecting the measurement result and its associated measurement uncertainty and enable the repetition of the laboratory activity under conditions as close as possible to the original. The technical records shall include the date and the identity of personnel responsible for each laboratory activity and for checking data and results. Original observations, data and calculations shall be recorded at the time they are made and shall be identifiable with the specific task.' },
  { clauseNo: '7.5.2', clauseMatter: 'The laboratory shall ensure that amendments to technical records can be tracked to previous versions or to original observations. Both the original and amended data and files shall be retained, including the date of alteration, an indication of the altered aspects and the personnel responsible for the alterations.' },
  { clauseNo: '7.6', clauseMatter: 'Evaluation of measurement uncertainty' },
  { clauseNo: '7.6.1', clauseMatter: 'Laboratories shall identify the contributions to measurement uncertainty. When evaluating measurement uncertainty, all contributions that are of significance, including those arising from sampling, shall be taken into account using appropriate methods of analysis.' },
  { clauseNo: '7.6.2', clauseMatter: 'A laboratory performing calibrations, including of its own equipment, shall evaluate the measurement uncertainty for all calibrations.' },
  { clauseNo: '7.6.3', clauseMatter: 'A laboratory performing testing shall evaluate measurement uncertainty. Where the test method precludes rigorous evaluation of measurement uncertainty, an estimation shall be made based on an understanding of the theoretical principles or practical experience of the performance of the method.NOTE 1: In those cases where a well-recognized test method specifies limits to the values of the major sources of measurement uncertainty and specifies the form of presentation of the calculated results, the laboratory is considered to have satisfied 7.6.3 by following the test method and reporting instructions.NOTE 2: For a particular method where the measurement uncertainty of the results has been established and verified, there is no need to evaluate measurement uncertainty for each result if the laboratory can demonstrate that the identified critical influencing factors are under control.NOTE 3: For further information, see ISO/IEC Guide 98-3, ISO 21748 and the ISO 5725 series.' },
  { clauseNo: '7.7', clauseMatter: 'Ensuring the validity of results' },
  { clauseNo: '7.7.1', clauseMatter: 'The laboratory shall have a procedure for monitoring the validity of results. The resulting data shall be recorded in such a way that trends are detectable and, where practicable, statistical techniques shall be applied to review the results. This monitoring shall be planned and reviewed and shall include, where appropriate, but not be limited to; a) use of reference materials or quality control materials; b) use of alternative instrumentation that has been calibrated to provide traceable results; c) functional check(s) of measuring and testing equipment; d) use of check or working standards with control charts, where applicable; e) intermediate checks on measuring equipment; f) replicate tests or calibrations using the same or different methods; g) retesting or recalibration of retained items; h) correlation of results for different characteristics of an item; i) review of reported results; j) intralaboratory comparisons; k) testing of blind sample(s).' },
  { clauseNo: '7.7.2', clauseMatter: 'The laboratory shall monitor its performance by comparison with results of other laboratories, where available and appropriate. This monitoring shall be planned and reviewed and shall include, but not be limited to, either or both of the following; a) participation in proficiency testing;NOTE: ISO/IEC 17043 contains additional information on proficiency tests and proficiency testing providers. Proficiency testing providers that meet the requirements of ISO/IEC 17043 are considered to be competent.; b) participation in interlaboratory comparisons other than proficiency testing.' },
  { clauseNo: '7.7.3', clauseMatter: 'Data from monitoring activities shall be analysed, used to control and, if applicable, improve the laboratory\'s activities. If the results of the analysis of data from monitoring activities are found to be outside pre-defined criteria, appropriate action shall be taken to prevent incorrect results from being reported.' },
  { clauseNo: '7.8', clauseMatter: 'Reporting of results' },
  { clauseNo: '7.8.1', clauseMatter: 'General' },
  { clauseNo: '7.8.1.1', clauseMatter: 'The results shall be reviewed and authorized prior to release.' },
  { clauseNo: '7.8.1.2', clauseMatter: 'The results shall be provided accurately, clearly, unambiguously and objectively, usually in a report (e.g. a test report or a calibration certificate or report of sampling), and shall include all the information agreed with the customer and necessary for the interpretation of the results and all information required by the method used. All issued reports shall be retained as technical records.NOTE 1 For the purposes of this document, test reports and calibration certificates are sometimes referred to as test certificates and calibration reports, respectively.NOTE 2 Reports can be issued as hard copies or by electronic means, provided that the requirements of this document are met.' },
  { clauseNo: '7.8.1.3', clauseMatter: 'When agreed with the customer, the results may be reported in a simplified way. Any information listed in 7.8.2 to 7.8.7 that is not reported to the customer shall be readily available.' },
  { clauseNo: '7.8.2', clauseMatter: 'Common requirements for reports (test, calibration or sampling)' },
  { clauseNo: '7.8.2.1', clauseMatter: 'Each report shall include at least the following information, unless the laboratory has valid reasons for not doing so, thereby minimizing any possibility of misunderstanding or misuse; a) a title (e.g. “Test Report” or “Calibration Certificate” or “Report of Sampling”); b) the name and address of the laboratory; c) the location of performance of the laboratory activities, including when performed at a customer facility or at sites away from the laboratory’s permanent facilities, or in associated temporary or mobile facilities; d) unique identification that all its components are recognized as a portion of a complete report and a clear identification of the end; e) the name and contact information of the customer; f) identification of the method used; g) a description, unambiguous identification, and, when necessary, the condition of the item; h) the date of receipt of the test or calibration item(s), and the date of sampling, where this is critical to the validity and application of theresults; i) the date(s) of performance of the laboratory activity; j) the date of issue of the report; k) reference to the sampling plan and sampling method used by the laboratory or other bodies where these are relevant to the validity or application of the results; l) a statement to the effect that the results relate only to the items tested, calibrated or sampled; m) the results with, where appropriate, the units of measurement; n) additions to, deviations, or exclusions from the method; o) identification of the person(s) authorizing the report; p) clear identification when results are from external providers. NOTE: Including a statement specifying that the report shall not be reproduced except in full without approval of the laboratory can provide assurance that parts of a report are not taken out of context.' },
  { clauseNo: '7.8.2.2', clauseMatter: 'The laboratory shall be responsible for all the information provided in the report, except when information is provided by the customer. Data provided by a customer shall be clearly identified. In addition, a disclaimer shall be put on the reportwhen the information is supplied by the customer and can affect the validity of results. Where the laboratory has not been responsible for the sampling stage (e.g. the sample has been provided by the customer), it shall state in the report that the results apply to the sample as received.' },
  { clauseNo: '7.8.3', clauseMatter: 'Specific requirements for test reports' },
  { clauseNo: '7.8.3.1', clauseMatter: 'In addition to the requirements listed in 7.8.2, test reports shall, where necessary for the interpretation of the test results, include the following; a) information on specific test conditions, such as environmental conditions; b) where relevant, a statement of conformity with requirements or specifications (see 7.8.6); c) where applicable, the measurement uncertainty presented in the same unit as that of the measurand or in a term relative to the measurand (e.g. percent) when it is relevant to the validity or application of the test results; a customer\'s instruction so requires, or the measurement uncertainty affects conformity to a specification limit; d) where appropriate, opinions and interpretations (see 7.8.7); e) additional information that may be required by specific methods, authorities, customersor groups of customers.' },
  { clauseNo: '7.8.3.2', clauseMatter: 'Where the laboratory is responsible for the sampling activity, test reports shall meet the requirements listed in 7.8.5 where necessary for the interpretation of test results.' },
  { clauseNo: '7.8.4', clauseMatter: 'Specific requirements for calibration certificates' },
  { clauseNo: '7.8.4.1', clauseMatter: 'In addition to the requirements listed in 7.8.2, calibration certificates shall include the following; a) the measurement uncertainty of the measurement result presented in the same unit as that of the measurand or in a term relative to the measurand (e.g. percent);NOTE: According to ISO/IEC Guide 99, a measurement result is generally expressed as a single measured quantity value including unit of measurement and a measurement uncertainty.; b) the conditions (e.g. environmental) under which the calibrations were made that have an influence on the measurement results; c) a statement identifying how the measurements are metrologically traceable (see Annex A); d) the results before and after any adjustment or repair, if available; e) where relevant, a statement of conformity with requirements or specifications (see 7.8.6); f) where appropriate, opinions and interpretations (see 7.8.7).' },
  { clauseNo: '7.8.4.2', clauseMatter: 'Where the laboratory is responsible for the sampling activity, calibration certificates shall meet the requirements listed in 7.8.5 where necessary for the interpretation of calibration results.' },
  { clauseNo: '7.8.4.3', clauseMatter: 'A calibration certificate or calibration label shall not contain any recommendation on the calibration interval, except where this has been agreed with the customer.' },
  { clauseNo: '7.8.5', clauseMatter: 'Reporting sampling - specific requirements Where the laboratory is responsible for the sampling activity, in addition to the requirements listed in 7.8.2, reports shall include the following, where necessary for the interpretation of results; a) the date of sampling; b) unique identification of the item or materialsampled (including the name of the manufacturer, the model or type of designation and serial numbers, as appropriate); c) the location of sampling, including any diagrams, sketches or photographs; d) a reference to the sampling plan and sampling method; e) details of any environmental conditions during sampling that affect the interpretationof the results; f) information required to evaluate measurement uncertainty for subsequent testing or calibration.' },
  { clauseNo: '7.8.6', clauseMatter: 'Reporting statements of conformity' },
  { clauseNo: '7.8.6.1', clauseMatter: 'When a statement of conformity to a specification or standard is provided, the laboratory shall document the decision rule employed, taking into account the level of risk (such as false accept and false reject and statistical assumptions) associated with the decision rule employed, and apply the decision rule.NOTE: Where the decision rule is prescribed by the customer, regulations or normative documents, a further consideration of the level of risk is not necessary.' },
  { clauseNo: '7.8.6.2', clauseMatter: 'The laboratory shall report on the statement of conformity, such that the statement clearly identifies; a) to which results the statement of conformity applies; b) which specifications, standards or parts thereof are met or not met; c) the decision rule applied (unless it is inherent in the requested specification or standard). NOTE For further information, see ISO/IEC Guide 98-4.' },
  { clauseNo: '7.8.7', clauseMatter: 'Reporting opinions and interpretations' },
  { clauseNo: '7.8.7.1', clauseMatter: 'When opinions and interpretations are expressed, the laboratory shall ensure that only personnel authorized for the expression of opinions and interpretations release the respective statement. The laboratory shall document the basis upon which the opinions and interpretations have been made.NOTE: It is important to distinguish opinions and interpretations from statements of inspections and product certifications as intended in ISO/IEC 17020 and ISO/IEC 17065, and from statements of conformity as referred to in 7.8.6.' },
  { clauseNo: '7.8.7.2', clauseMatter: 'The opinions and interpretations expressed in reports shall be based on the results obtained from the tested or calibrated item and shall be clearly identified as such.' },
  { clauseNo: '7.8.7.3', clauseMatter: 'When opinions and interpretations are directly communicated by dialogue with the customer, a record of the dialogue shall be retained.' },
  { clauseNo: '7.8.8', clauseMatter: 'Amendments to reports' },
  { clauseNo: '7.8.8.1', clauseMatter: 'When an issued report needs to be changed, amended or re-issued, any change of information shall be clearly identified and, where appropriate, the reason for the change included in the report.' },
  { clauseNo: '7.8.8.2', clauseMatter: 'Amendments to a report after issue shall be made only in the form of a further document, or data transfer, which includes the statement “Amendment to Report, serial number... [or as otherwise identified]”, or an equivalent form of wording. Such amendments shall meet all the requirements of this document.' },
  { clauseNo: '7.8.8.3', clauseMatter: 'When it is necessary to issue a complete new report, this shall be uniquely identified and shall contain a reference to the original that it replaces.' },
  { clauseNo: '7.9', clauseMatter: 'Complaints' },
  { clauseNo: '7.9.1', clauseMatter: 'The laboratory shall have a documented process to receive, evaluate and make decisions on complaints.' },
  { clauseNo: '7.9.2', clauseMatter: 'A description of the handling process for complaints shall be available to any interested party on request. Upon receipt of a complaint, the laboratory shall confirm whether the complaint relates to laboratory activities that it is responsible for and, if so, shall deal with it. The laboratory shall be responsible for all decisions at all levels of the handling process for complaints.' },
  { clauseNo: '7.9.3', clauseMatter: 'The process for handling complaints shall include at least the following elements and methods; a) description of the process for receiving, validating, investigating the complaint, and deciding what actions are to be taken in response to it; b) tracking and recording complaints, including actions undertaken to resolve them; c) ensuring that any appropriate action is taken.' },
  { clauseNo: '7.9.4', clauseMatter: 'The laboratory receiving the complaint shall be responsible for gathering and verifying all necessary information to validate the complaint.' },
  { clauseNo: '7.9.5', clauseMatter: 'Whenever possible, the laboratory shall acknowledge receipt of the complaint, and provide the complainant with progress reports and the outcome.' },
  { clauseNo: '7.9.6', clauseMatter: 'The outcomes to be communicated to the complainant shall be made by, or reviewed and approved by, individual(s) not involved in the original laboratory activities in question.NOTE: This can be performed by external personnel.' },
  { clauseNo: '7.9.7', clauseMatter: 'Whenever possible, the laboratory shall give formal notice of the end of the complaint handling to the complainant.' },
  { clauseNo: '7.10', clauseMatter: 'Nonconforming Work' },
  { clauseNo: '7.10.1', clauseMatter: 'The laboratory shall have a procedure that shall be implemented when any aspect of its laboratory activities or results of this work do not conform to its own procedures or the agreed requirements of the customer (e.g. equipment or environmental conditions are out of specified limits, results of monitoring fail to meet specified criteria). The procedure shall ensure that; a) the responsibilities and authorities for the management of nonconforming work are defined; b) actions (including halting or repeating of work and withholding of reports, as necessary) are based upon the risk levels established by the laboratory; c) an evaluation is made of the significance of the nonconforming work, including an impact analysis on previous results; d) a decision is taken on the acceptability of the nonconforming work; e) where necessary, the customer is notified and work is recalled; f) the responsibility for authorizing the resumption of work is defined.' },
  { clauseNo: '7.10.2', clauseMatter: 'The laboratory shall retain records of nonconforming work and actions as specified in 7.10.1, bullets b) to f).' },
  { clauseNo: '7.10.3', clauseMatter: 'Where the evaluation indicates that the nonconforming work could recur, or that there is doubt about the conformity of the laboratory\'s operations with its own management system, the laboratory shall implement corrective action.' },
  { clauseNo: '7.11', clauseMatter: 'Control of data and information management' },
  { clauseNo: '7.11.1', clauseMatter: 'The laboratory shall have access to the data and information needed to perform laboratory activities.' },
  { clauseNo: '7.11.2', clauseMatter: 'The laboratory information management system(s) used for the collection, processing, recording, reporting, storage or retrieval of data shall be validated for functionality, including the proper functioning of interfaces within the laboratoryinformation management system(s) by the laboratory before introduction. Whenever there are any changes, including laboratory software configuration or modifications to commercial off the-shelf software, they shall be authorized,documented and validated before implementation.NOTE 1: In this document laboratory information management system(s) includes the management of data and information contained in both computerized and non-computerized systems. Some of the requirements can be more applicable to computerized systems than to non-computerized systems.NOTE 2: Commercial off-the-shelf software in general use within its designed application range can be considered to be sufficiently validated.' },
  { clauseNo: '7.11.3', clauseMatter: 'The laboratory information management system(s) shall; a) be protected from unauthorized access; b) be safeguarded against tampering and loss; c) be operated in an environment that complies with provider or laboratory specifications or, in the case of noncomputerized systems, provides conditions which safeguard the accuracy of manual recording and transcription; d) be maintained in a manner that ensures the integrity of the data and information; e) include recording system failures and the appropriate immediate and corrective actions.' },
  { clauseNo: '7.11.4', clauseMatter: 'When a laboratory information management system is managed and maintained off-site or through an external provider, the laboratory shall ensure that the provider or operator of the system complies with all applicable requirements of this document.' },
  { clauseNo: '7.11.5', clauseMatter: 'The laboratory shall ensure that instructions, manuals and reference data relevant to the laboratory information management system(s) are made readily available to personnel.' },
  { clauseNo: '7.11.6', clauseMatter: 'Calculations and data transfers shall be checked in an appropriate and systematic manner. 8 Management System Requirements' },
  { clauseNo: '8.1', clauseMatter: 'Options' },
  { clauseNo: '8.1.1', clauseMatter: 'General General: The laboratory shall establish, document, implement and maintain a management system that is capable of supporting and demonstrating the consistent achievement of the requirements of this document and assuring the quality of the laboratory results. In addition to meeting the requirements of Clauses 4 to 7, the laboratory shall implement a management system in accordance with Option A or Option B. NOTE: See Annex B for more information.' },
  { clauseNo: '8.1.2', clauseMatter: 'Option A As a minimum, the management system of the laboratory shall address the following: management system documentation (see 8.2); control of management system documents (see 8.3);control of records (see 8.4); actions to address risks and opportunities (see 8.5);improvement (see 8.6);corrective actions (see 8.7); internal audits (see 8.8); management reviews (see 8.9)' },
  { clauseNo: '8.1.3', clauseMatter: 'Option B A laboratory that has established and maintains a management system, in accordance with the requirements of ISO 9001, and that is capable of supporting and demonstrating the consistent fulfilment of the requirements of Clauses 4 to 7, also fulfils at least the intent of the management system requirements specified in 8.2 to 8.9.' },
  { clauseNo: '8.2', clauseMatter: 'Management system documentation (Option A)' },
  { clauseNo: '8.2.1', clauseMatter: 'Laboratory management shall establish, document, and maintain policies and objectives for the fulfilment of the purposes of this document and shall ensure that the policies and objectives are acknowledged and implemented at all levels of the laboratory organization.' },
  { clauseNo: '8.2.2', clauseMatter: 'The policies and objectives shall address the competence, impartiality and consistent operation of the laboratory.' },
  { clauseNo: '8.2.3', clauseMatter: 'Laboratory management shall provide evidence of commitment to the development and implementation of the management system and to continually improving its effectiveness.' },
  { clauseNo: '8.2.4', clauseMatter: 'All documentation, processes, systems, records, related to the fulfilment of the requirements of this document shall be included in, referenced from, or linked to the management system.' },
  { clauseNo: '8.2.5', clauseMatter: 'All personnel involved in laboratory activities shall have access to the parts of the management system documentation and related information that are applicable to their responsibilities.' },
  { clauseNo: '8.3', clauseMatter: 'Control of management system documents (Option A)' },
  { clauseNo: '8.3.1', clauseMatter: 'The laboratory shall control the documents (internal and external) that relate to the fulfilment of this document. NOTE: In this context, “documents” can be policy statements, procedures, specifications, manufacturer’s instructions, calibration tables, charts, text books, posters, notices, memoranda, drawings, plans, etc. These can be on various media, such as hard copy or digital.' },
  { clauseNo: '8.3.2', clauseMatter: 'The laboratory shall ensure that; a) documents are approved for adequacy prior to issue by authorized personnel; b) documents are periodically reviewed, and updated as necessary; c) changes and the current revision status of documents are identified; d) relevant versions of applicable documents are available at points of use and, where necessary, their distribution is controlled; e) documents are uniquely identified; f) the unintended use of obsolete documents is prevented, and suitable identification is applied to them if they are retained for any purpose' },
  { clauseNo: '8.4', clauseMatter: 'Control of records (Option A)' },
  { clauseNo: '8.4.1', clauseMatter: 'The laboratory shall establish and retain legible records to demonstrate fulfilment of the requirements in this document.' },
  { clauseNo: '8.4.2', clauseMatter: 'The laboratory shall implement the controls needed for the identification, storage, protection, back-up, archive, retrieval, retention time, and disposal of its records. The laboratory shall retain records for a period consistent with its contractual obligations. Access to these records shall be consistent with the confidentiality commitments, and records shall be readily available.NOTE: Additional requirements regarding technical records are given in 7.5.' },
  { clauseNo: '8.5', clauseMatter: 'Actions to address risks and opportunities (Option A)' },
  { clauseNo: '8.5.1', clauseMatter: 'The laboratory shall consider the risks and opportunities associated with the laboratory activities in order to; a) give assurance that the management system achieves its intended results; b) enhance opportunities to achieve the purpose and objectives of the laboratory; c) prevent, or reduce, undesired impacts and potential failures in the laboratory activities; d) achieve improvement.' },
  { clauseNo: '8.5.2', clauseMatter: 'The laboratory shall plan; a) actions to address these risks and opportunities; b) How to: integrate and implement the sections into its management system; evaluate the effectiveness of the sections.NOTE: Although this document specifies that the laboratory plans actions to address risks, there is no requirement for formal methods for risk management or a documented risk management process. Laboratories can decide whether or not to develop a more extensive risk management methodology than is required by this document, e.g. Through the application of other guidance or standards.' },
  { clauseNo: '8.5.3', clauseMatter: 'Actions taken to address risks and opportunities shall be proportional to the potential impact on the validity of laboratory results. NOTE 1: Options to address risks can include identifying and avoiding threats, taking risk in order to pursue an opportunity, eliminating the risk source, changing the likelihood or consequences, sharing the risk, or retaining risk by informed decision. NOTE 2: Opportunities can lead to expanding the scope of the laboratory activities, addressing new customers, using new technology and other possibilities to address customer needs.' },
  { clauseNo: '8.6', clauseMatter: 'Improvement (Option A)' },
  { clauseNo: '8.6.1', clauseMatter: 'The laboratory shall identify and select opportunities for improvement and implement any necessary actions. NOTE: Opportunities for improvement can be identified through the review of the operational procedures, the use of the policies, overall objectives, audit results, corrective actions, management review, suggestions from personnel, risk assessment, analysis of data, and proficiency testing results.' },
  { clauseNo: '8.6.2', clauseMatter: 'The laboratory shall seek feedback, both positive and negative, from its customers. The feedback shall be analysed and used to improve the management system, laboratory activities and customer service. NOTE: Examples of the types of feedback include customer satisfaction surveys, communication records and review of reports with customers.' },
  { clauseNo: '8.7', clauseMatter: 'Corrective actions (Option A)' },
  { clauseNo: '8.7.1', clauseMatter: 'When a nonconformity occurs, the laboratory shall; a) react to the nonconformity and, as applicable; take action to control and correct it; address the consequences; b) evaluate the need for action to eliminate the cause(s) of the nonconformity, in order that it does not recur or occur elsewhere, by reviewing and analysing the nonconformity;determining the causes of the nonconformity;determining if similar nonconformities exist, or could potentially occur; c) implement any action needed; d) review the effectiveness of any corrective action taken; e) update risks and opportunities determined during planning, if necessary; f) make changes to the management system, if necessary.' },
  { clauseNo: '8.7.2', clauseMatter: 'Corrective actions shall be appropriate to the effects of the nonconformities encountered.' },
  { clauseNo: '8.7.3', clauseMatter: 'The laboratory shall retain records as evidence of; a) the nature of the nonconformities, cause(s) and any subsequent actions taken; b) the results of any corrective action.s' },
  { clauseNo: '8.8', clauseMatter: 'Internal audits (Option A)' },
  { clauseNo: '8.8.1', clauseMatter: 'The laboratory shall conduct internal audits at planned intervals to provide information on whether the management system; a) conforms to the laboratory’s own requirements for its management system, including the laboratory activities; the requirements of this document; b) is effectively implemented and maintained' },
  { clauseNo: '8.8.2', clauseMatter: 'The laboratory shall; a) plan, establish, implement and maintain an audit programme including the frequency, methods, responsibilities, planning requirements and reporting, which shall take into consideration the importance of the laboratory activities concerned, changes affecting the laboratory, and the results of previous audits; b) define the audit criteria and scope for each audit; c) ensure that the results of the audits are reported to relevant management; d) implement appropriate correction and corrective actions without undue delay; e) retain records as evidence of the implementation of the audit programme and the audit results.NOTE: ISO 19011 provides guidance for internal audits.' },
  { clauseNo: '8.9', clauseMatter: 'Management reviews (Option A)' },
  { clauseNo: '8.9.1', clauseMatter: 'The laboratory management shall review its management system at planned intervals, in order to ensure its continuing suitability, adequacy and effectiveness, including the stated policies and objectives related to the fulfilment of this document.' },
  { clauseNo: '8.9.2', clauseMatter: 'The inputs to management review shall be recorded and shall include information related to the following; a) changes in internal and external issues that are relevant to the laboratory; b) fulfilment of objectives; c) suitability of policies and procedures; d) status of actions from previous management reviews; e) outcome of recent internal audits; f) corrective actions; g) assessments by external bodies; h) changes in the volume and type of the work or in the range of laboratory activities; i) customer and personnel feedback; j) complaints; k) effectiveness of any implemented improvements; l) adequacy of resources; m) results of risk identification; n) outcomes of the assurance of the validity of results; and; o) other relevant factors, such as monitoring activities and training.' },
  { clauseNo: '8.9.3', clauseMatter: 'The outputs from the management review shall record all decisions and actions related to at least; a) the effectiveness of the management system and its processes; b) improvement of the laboratory activities related to the fulfilment of the requirements of this document; c) provision of required resources; d) any need for change.' },
]

